cssCode:
.neumorphic-btn {
  width: 120px; height: 120px;
  border-radius: 50%;
  background: #e0e5ec;
  border: none;
  box-shadow: 10px 10px 20px #a3b1c6, -10px -10px 20px #ffffff;
  display: flex; align-items: center; justify-content: center;
  font-size: 40px; color: #6c63ff;
  cursor: pointer;
  transition: box-shadow 0.2s ease, transform 0.1s;
}
.neumorphic-btn:active {
  box-shadow: inset 10px 10px 20px #a3b1c6, inset -10px -10px 20px #ffffff;
  transform: scale(0.95);
  color: #ff007f;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const btn = document.createElement('button');
btn.className = 'neumorphic-btn';
btn.innerText = '▶';

c.appendChild(btn);
